%[text] # 概要
%[text] ```
%[text] 実機を対象とした System Identification 用の 実験ファイル。
%[text] `run_si_demo.m` の流れを土台にしつつ、VirtualMotor への ADS 書き込みは行わず、
%[text] 解析時のみ nominal 2-inertia model を重ねて実機運用向けに整理している。
%[text] ```
%[text] ```
%[text] 注意:
%[text]   - 本ファイルは実機用であり、現在の数値はあくまで安全側の例である
%[text]   - 実行前に機械系の可動範囲、非常停止、配線、logger 保存先を確認すること
%[text]   - 実験条件に応じて chirp 振幅、周波数帯、repeat 数を調整すること
%[text] ```
%[text] ## 前提確認
%[text] ```
%[text] - TwinCAT は実機マッピング側の project / runtime を使用していること
%[text] - ExperimentLogger が `SystemConfig.LOGGER_DEFAULT_FILE_PATH` に書き込めること
%[text] - chirp 注入中に過電流、衝突、過大変位が起きない条件であること
%[text] - `ff_value -> load_velocity` の FRF を取得する目的で、ref=0 / dist=0 を使うこと
%[text] ```
%[text] ## セットアップ
%[text] `run('matlab/setup_matlab_environment.m')` を一度実行し、起動時 PATH 設定が完了していること。

sys = config.SystemConfig;
cfg = experiment.ExperimentConfig.defaults();
logger_file_glob = "*.bin";
logger_dir = string(fileparts(char(sys.LOGGER_DEFAULT_FILE_PATH)));
%%
%[text] ## 例示パラメータ
%[text] 実機で試しやすい保守的な例。現場の条件に合わせて調整すること。
Ts = 1 / cfg.task_rate_hz;
Tend = 10;
Tcycle = 10;
repeat_count = 10;
f0 = 0.5;
f1 = 4000;
A = 0.1;
transient_cycles = 3;
initial_phase = 0;
hold_margin_s = 1.0;
Kp = 0;
%%
%[text] ## chirp 生成
nyquist_guard_hz = 0.5 / Ts;
f1_effective = min(f1, nyquist_guard_hz);
if f1_effective < f1
  warning("experiment:exp01_SI:f1Clamped", ...
    "Requested f1=%.3f Hz exceeds Nyquist guard; using %.3f Hz instead.", ...
    f1, f1_effective);
end

chirp_cfg = experiment.build_periodic_chirp( ...
  "Ts", Ts, ...
  "Tend", Tend, ...
  "Tcycle", Tcycle, ...
  "f0", f0, ...
  "f1", f1_effective, ...
  "A", A, ...
  "initial_phase", initial_phase);
sample_n = chirp_cfg.sample_count;

figure; %[output:65636e1c]
plot(chirp_cfg.signal) %[output:65636e1c]
title("Chirp Signal"); %[output:65636e1c]
xlabel("Sample"); %[output:65636e1c]
ylabel("Amplitude"); %[output:65636e1c]
%%
%[text] ## 実験実行
cfg.ref_profile = zeros(sample_n, 1);
cfg.ff_profile = chirp_cfg.signal(:);
cfg.dist_profile = zeros(sample_n, 1);
cfg.repeat_count = repeat_count;
cfg.wait_for_done = true;
cfg.hold_seconds = Tend + hold_margin_s;
cfg.done_timeout_s = repeat_count * Tend + hold_margin_s + 5.0;
cfg.logger_release_timeout_s = max(5.0, repeat_count * Tend / 10);
cfg.controller = experiment.ControllerConfig.p_only(Kp);
% Analysis-only nominal plant for FRF overlay; do not write this to ADS.
vm_cfg = virtualMotor.PlantConfig.from_struct(struct( ...
  "motor", struct( ...
    "inertia", 0.02, ...
    "damping", 0.2, ...
    "ratedTorque", 1.2, ...
    "tauLimit", 2.4, ...
    "velLimit", 2*pi*60, ...
    "maxPermille", 0.0, ...
    "encoderResolution", uint32(8388608)), ...
  "load", struct( ...
    "inertia", 0.03, ...
    "damping", 0.15, ...
    "ratedTorque", 1.2, ...
    "tauLimit", 2.4, ...
    "velLimit", 2*pi*60, ...
    "encoderResolution", uint32(8388608)), ...
  "coupling", struct( ...
    "stiffness", 50.0, ...
    "damping", 0.5)));

status_text = struct();
status_text.header = sprintf("=== Real Motor SI Template ===\n");
status_text.config_line = sprintf("Ts=%.6f s, Tend=%.3f s, Tcycle=%.3f s, repeats=%d, total=%.3f s, A=%.3f\n", ...
  Ts, Tend, Tcycle, repeat_count, repeat_count * Tend, A);
status_text.band_line = sprintf("f0=%.3f Hz, f1(requested)=%.3f Hz, f1(effective)=%.3f Hz, transient_cycles=%d\n", ...
  f0, f1, f1_effective, transient_cycles);
status_text.logger_line = sprintf("Samples=%d, cycles=%.2f, loggerDir=%s\n", sample_n, chirp_cfg.cycle_count, logger_dir);

conn = experiment.ConnectionManager.create(cfg);
cleanup = onCleanup(@() conn.session.close()); 
status_text.connection_line = sprintf("Connected: SEQ=%d, CTRL=%d, MODULE=%d\n", cfg.seq_port, cfg.control_port, cfg.module_port);

run_out = experiment.ExperimentRunner.run(conn, cfg);
latest_bin = experiment.read_latest_logger_bin(logger_dir, logger_file_glob);
if ~latest_bin.ok
  error("experiment:exp01_SI:loggerUnavailable", ...
    "ExperimentLogger bin is unavailable (%s).", string(latest_bin.reason));
end
logger_bin = latest_bin.logger_bin;
%%
%[text] ## FRF 解析
frf_out = experiment.analyze_si_frf(logger_bin, ...
  "Ts", Ts, ...
  "Tcycle", Tcycle, ...
  "transient_cycles", transient_cycles);

status_text.result_header = sprintf("\n--- Result ---\n");
status_text.run_line = sprintf("done=%d timed_out=%d\n", logical(run_out.host.done), logical(run_out.host.timed_out));
status_text.result_logger_line = sprintf("logger=%s records=%d file=%s\n", ...
  string(latest_bin.reason), logger_bin.record_count, string(logger_bin.file_path));
status_text.frf_line = sprintf("FRF input=%s output=%s windowSamples=%d usablePeriods=%d\n", ...
  frf_out.input_signal_name, frf_out.output_signal_name, ...
  frf_out.window_samples, frf_out.trim_info.usable_period_count);

if any(frf_out.coherence < 0.2)
  warning("experiment:exp01_SI:lowCoherence", ...
    "Coherence drops below 0.2 in part of the analyzed band.");
end
%%
%[text] ## 可視化
freq_hz = frf_out.freq_hz(:);
omega_rad_s = 2 * pi * freq_hz;
frf_measured = frf_out.frf(:);
frf_nominal = compute_nominal_two_inertia_frf( ...
  vm_cfg, omega_rad_s, ...
  "Ts", Ts, ...
  "sample_delay", 4);
mag_measured_db = mag2db(abs(frf_measured));
mag_nominal_db = mag2db(abs(frf_nominal));
phase_measured_deg = experiment.wrap_phase_at_180(rad2deg(unwrap(angle(frf_measured))));
phase_nominal_deg = experiment.wrap_phase_at_180(rad2deg(unwrap(angle(frf_nominal))));

figure("Name", "Real Motor SI", "Color", "w"); %[output:72a800d2]
tiledlayout(3, 1, "Padding", "compact", "TileSpacing", "compact"); %[output:72a800d2]

nexttile; %[output:72a800d2]
semilogx(freq_hz, mag_measured_db, "-", "LineWidth", 1.2, "DisplayName", "Measured"); hold on; %[output:72a800d2]
semilogx(freq_hz, mag_nominal_db, "--", "LineWidth", 1.2, "DisplayName", "Nominal"); %[output:72a800d2]
hold off; %[output:72a800d2]
grid on; %[output:72a800d2]
xlabel("Frequency [Hz]"); %[output:72a800d2]
ylabel("Gain [dB]"); %[output:72a800d2]
legend("Location", "best"); %[output:72a800d2]
title("FRF Gain: ffValue -> loadVelocity"); %[output:72a800d2]

nexttile; %[output:72a800d2]
semilogx(freq_hz, phase_measured_deg, "-", "LineWidth", 1.2, "DisplayName", "Measured"); hold on; %[output:72a800d2]
semilogx(freq_hz, phase_nominal_deg, "--", "LineWidth", 1.2, "DisplayName", "Nominal"); %[output:72a800d2]
hold off; %[output:72a800d2]
grid on; %[output:72a800d2]
xlabel("Frequency [Hz]"); %[output:72a800d2]
ylabel("Phase [deg]"); %[output:72a800d2]
ylim([-180, 180]); %[output:72a800d2]
yticks([-180, -135, -90, -45, 0, 45, 90, 135, 180]); %[output:72a800d2]
legend("Location", "best"); %[output:72a800d2]
title("FRF Phase: ffValue -> loadVelocity"); %[output:72a800d2]

nexttile; %[output:72a800d2]
semilogx(freq_hz, frf_out.coherence, "-", "LineWidth", 1.2); %[output:72a800d2]
grid on; %[output:72a800d2]
xlabel("Frequency [Hz]"); %[output:72a800d2]
ylabel("Coherence"); %[output:72a800d2]
ylim([0, 1.05]); %[output:72a800d2]
title(sprintf("Coherence (transient cycles removed = %d)", transient_cycles)); %[output:72a800d2]

si_out = struct( ...
  "run", run_out, ...
  "logger_bin", logger_bin, ...
  "frf", frf_out, ...
  "chirp", chirp_cfg); 
%%
%[text] ## 次の調整指針
%[text] ```
%[text] - `A` は 0.1 から始め、飽和や異常振動がなければ段階的に上げる
%[text] - `repeat_count` を増やす前に単発で logger と coherence を確認する
%[text] - `f1` は機械共振帯とサンプリング上限の両方を見て設定する
%[text] - coherence が低い帯域は振幅不足、非線形、ログ不足を疑う
%[text] - 必要なら `si_out` を起点に Live Editor 上で追加解析を行う
%[text] ```

function frf_nominal = compute_nominal_two_inertia_frf(plant_cfg, omega_rad_s, varargin)
parser = inputParser;
parser.addParameter("Ts", [], @(x) isempty(x) || (isnumeric(x) && isscalar(x) && isfinite(x) && x > 0));
parser.addParameter("sample_delay", 0, @(x) isnumeric(x) && isscalar(x) && isfinite(x) && x >= 0);
parser.parse(varargin{:});
args = parser.Results;

s = 1i * omega_rad_s(:);
s(abs(s) == 0) = 1i * eps;
plant = plant_cfg.to_struct();
jm = plant.motor.inertia;
jl = plant.load.inertia;
bm = plant.motor.damping;
bl = plant.load.damping;
ks = plant.coupling.stiffness;
ds = plant.coupling.damping;
c = ds + ks ./ s;
den = (jm .* s + bm + c) .* (jl .* s + bl + c) - c .* c;
frf_nominal = c ./ den;

sample_delay = double(args.sample_delay);
if sample_delay > 0
  if isempty(args.Ts)
    error("experiment:exp01_SI:invalidConfig", ...
      "Ts is required when sample_delay is nonzero.");
  end
  frf_nominal = frf_nominal .* exp(-s * args.Ts * sample_delay);
end
end

